  "exports.title": "导出与备份",
  "exports.subtitleStart": "下载始终仅限于",
  "exports.subtitleRest": "。每个文件都会标注商家名称和制作日期。",
  "exports.createBusinessFirst": "请先创建一个商家——导出属于某个商家，而不是属于本应用。",
  "exports.lockedTitle": "CSV 与 Excel 导出是 Business 套餐的功能",
  "exports.lockedDesc": "您的工作区目前是 Essentials 套餐。Business 套餐增加了 CSV 与 Excel 导出、库存估值、无限商品与员工、供应商、采购和组合商品。",
  "exports.seeBusiness": "查看 Business 套餐包含的内容",
  "exports.whatTheseAre": "这些文件是什么",
  "exports.about1": "每个数据集都提供 CSV 或真正的 Excel 工作簿（.xlsx）——完整库存工作簿仅提供 Excel 版本，每个数据集占一个工作表。CSV 文件可在 Excel、Numbers、Google Sheets 和大多数库存应用中打开。UTF-8 文本、带引号的逗号、备注中的换行以及编码前面的零都会保留，以公式开头的单元格会被处理为纯文本，以免电子表格将其当作公式。",
  "exports.about2": "在 Excel 文件中，SKU、UPC、ISBN 和条码都是文本单元格——绝不会变成科学计数法，也不会丢失前面的零——并已设置列宽、标题筛选以及货币或数量格式。完整库存工作簿将商品、库存量、位置和库存变动分别放在不同的工作表上。",
  "exports.about3": "非常大的导出每个数据集最多导出 20,000 行——达到上限时，文件名会注明（truncated-20000），因此不完整的文件永远不会被误认为完整文件。",
  "exports.about4": "备份是您数据的快照，不是用来一键恢复的。恢复需要手动操作并先行核对，因此请妥善保管该文件——应用目前无法用它重建已删除的商家。应用代码和 Base44 平台备份与这些文件分开处理。",
  "exports.about5": "照片和附件以其存储链接列出——图片文件本身不会打包进下载文件。",
  "exports.backupTitle": "完整备份",
