  "print.howToReach": "如何连接您的打印机",
  "print.howIntro": "本应用连接您已有的打印机——它本身不是打印机。共有四种连接方式，标签在两个套餐中通过其中任何一种都可以打印。装箱单、采购订单、供应商单据和报表是 Business 套餐专属的，无论采用哪种连接方式。",
  "print.howBluetoothLead": "Bluetooth。",
  "print.howBluetoothBody": "在本页面上，使用桌面版 Chrome 或 Edge 以及 Android 版 Chrome：选择您的标签打印机，标签便直接发送过去。在 iOS Safari 中无法使用——在 iPhone 上，Bluetooth 打印由移动应用提供。只支持 Zebra ZPL 或 Brother 自有语言的打印机无法理解本页面发送的标签；这一点已在真实打印机上验证后才称为可用。",
  "print.howWifiLead": "Wi-Fi。",
  "print.howWifiBody": "将打印机安装到您店铺的 Wi-Fi 上，然后使用“打印”按钮——通过安装在这台电脑上的打印机、经由店铺网络打印。在 iPhone 上，AirPrint 是内置功能：同一 Wi-Fi 上的 AirPrint 打印机直接出现在打印表单中，无需数据线也无需应用，本应用也无需任何 AirPrint 专用代码。打印机必须支持 AirPrint（大多数新打印机都支持），且手机和打印机必须在同一 Wi-Fi 上。",
  "print.howEthernetLead": "以太网。",
  "print.howEthernetBody": "用以太网线将打印机连接到店铺网络，安装到电脑上，然后通过“打印”按钮打印。以太网是桌面和电脑的路径——iPhone 不使用以太网线。",
  "print.howUsbLead": "USB。",
  "print.howUsbBody": "用数据线将打印机插入电脑，然后使用“打印”按钮——通过安装在该电脑上的打印机打印。在使用 USB OTG 数据线的 Android 手机上，上方的 USB 按钮可直接与打印机通信。iPhone 无法通过 USB 直接打印——那里没有 WebUSB——因此请使用 Wi-Fi / AirPrint，或移动应用中的 Bluetooth。",
  "print.howCordsLead": "数据线仍然能为 iPhone 服务，只是多了一步。",
  "print.howCordsBody": "插入店铺电脑的 USB 打印机，或连到网络的以太网打印机，会通过店铺 Wi-Fi（AirPrint / 共享打印机）出现在您的 iPhone 上——数据线让打印机稳稳地连上网络，手机再无线连接它。",
  "print.howOfflineLead": "如果断网，",
  "print.howOfflineBody": "本页面上已有的标签和单据仍然可以打印——“打印”按钮、标签 PDF、Bluetooth 和 USB 都无需联网。需要联网的是首次加载本页面及其商品。完全离线模式（完全没有网络时仍可在应用中工作）是一项更大、单独的开发工作，此处不作承诺。",
