  "settings.cancelTerms.intro": "这些是 Luminous StockHaven 付费订阅的条款。网站订阅通过 Stripe 计费。您可以随时使用下方的“取消订阅”按钮自行取消订阅——无需员工批准。取消和退款请求也可以通过官方客服联系方式 theluminousbookshop@outlook.com 处理。",
  "settings.cancelTerms.noApprovalBody": "您可以随时自行取消订阅，无需员工批准。后续续费仅在计费服务商确认取消后才会停止。",
  "settings.cancelTerms.noApprovalTitle": "无需批准即可取消：",
  "settings.cancelTerms.paymentBody": "付费试用要求在注册时提供付款方式。除非在适用的试用取消截止日期前取消，否则试用结束后将自动按所选月度套餐收费。价格、首次计费日期以及服务商特定的取消截止日期必须在注册时显示。试用计费通过 Stripe 进行。",
  "settings.cancelTerms.paymentTitle": "付款方式与自动续费：",
  "settings.cancelTerms.remainingBody": "如果您已支付某个计费周期，您可以在已验证的付费截止日期之前继续使用。提前终止需要服务商的相应确认以及适用的退款处理。免费试用按服务商确认的试用终止日期结束。",
  "settings.cancelTerms.remainingTitle": "剩余使用权限：",
  "settings.cancelTerms.storesBody": "如果您曾经通过 Google Play 或 Apple App Store 订阅，您的订阅由该应用商店计费和管理。您可能需要在用于订阅的同一 Google 或 Apple 账户的订阅管理页面中直接取消。取消另一份网站订阅、卸载本应用，或申请删除 Luminous StockHaven 账户，都不会自动取消通过应用商店计费的订阅。请查看您的购买收据以确认由谁向您收费。",
