  "staff.addFirst": "添加第一位员工",
  "staff.addMember": "添加员工",
  "staff.emptyBody": "添加一位人员，为其分配角色及相应权限，他们将收到邮件邀请，登录此店铺。",
  "staff.emptyTitle": "还没有员工",
  "staff.eyebrow": "团队",
  "staff.how.p1": "每位成员都有一个角色和自己的权限列表，因此您可以从某个角色出发，只改动其中一项，而无需新建角色。编辑角色不会改写已使用该角色的成员——请打开某位成员，重新应用其角色默认值。",
  "staff.how.p2": "自定义角色是 Business 套餐功能：Essentials 套餐使用五个内置角色（店主、经理、库存管理员、销售员、查看者）。",
  "staff.how.p3": "邀请通过邮件发送。成员只有接受邀请后才能登录；将某人从此列表中移除不会删除其应用账户。",
  "staff.how.p4": "门店是指某人被分配到的位置。它会记录在其员工卡上；而他们能打开哪些内容仍由其角色和权限决定。",
  "staff.how.p5": "权限决定每个人能打开哪些内容：角色之外的菜单项会被隐藏，访问受限的地址会显示“不在您的角色范围内”的提示，而不是页面本身。更改会在该人员下次加载应用时生效；暂停某位成员会将其完全锁定。",
  "staff.how.p6": "管理员可以查看和更改所有数据、管理应用用户和角色，并且不受任何员工角色限制。没有员工记录的人——例如新店铺的店主——仍拥有完整访问权限。",
