  "auth.sameEmailNotice": "已经从 Google Play 或 App Store 获得了我们的应用？请在此使用同一邮箱——您登录应用所用的邮箱——这样您的店铺和库存会随您而来。使用不同的邮箱会开启一个全新的、空的店铺。",
