  "settings.security.codesRemaining": "剩余未用备用验证码：{count}",
  "settings.security.generateCodes": "生成备用验证码",
  "settings.security.regenerateCodes": "生成一套新的",
  "settings.security.newCodesTitle": "您的新备用验证码",
  "settings.security.codesOnceWarning": "这些验证码只显示一次——我们只保存加密副本，因此连我们也无法再次显示。生成新的一套会使所有旧验证码失效。",
  "settings.security.printCodes": "打印这些验证码",
  "settings.security.backupEmailTitle": "备用邮箱",
  "settings.security.backupEmailDesc": "您掌握的第二个邮箱地址。如果您的主邮箱将来无法访问，恢复验证码可以发送到这里。",
  "settings.security.backupEmailLabel": "备用邮箱地址",
