  "workforce.tab.rewards": "奖励",
  "training.lessons.mgr-give-rewards.step1": "打开“员工管理”，点击“奖励”。选择团队成员，然后选择类型：店内折扣百分比、礼品卡，或您用自己的话描述的其他奖励。",
  "training.lessons.mgr-give-rewards.step2": "给奖励起一个简短名称，如愿意可加备注。该人员会立即收到铃铛通知，奖励会带着自己的验证码等在其“我的奖励”中。",
  "training.lessons.mgr-give-rewards.step3": "按设计的界限：您只能奖励员工。您不能奖励自己或另一位经理——奖励经理是店主的决定，应用会直言拒绝。",
  "training.lessons.mgr-give-rewards.step4": "在收银台，输入团队成员向您出示的验证码并标记为已使用——每个验证码只能使用一次。如果计划有变，您可以作废自己发放的奖励；店主的礼物由店主作废。",
  "training.lessons.mgr-give-rewards.title": "向您的员工发放奖励",
  "training.lessons.owner-give-rewards.step1": "奖励位于“员工管理”的“奖励”选项卡，且仅限 Business 套餐——在 Essentials 中，该选项卡显示一扇锁着的门，让您的团队看到更大套餐包含什么。",
  "training.lessons.owner-give-rewards.step2": "您可以奖励团队中的任何人——员工和经理都可以。选择人员，然后选择类型：店内折扣百分比（您选择的任意百分比）、任意地方的礼品卡，或您用自己的话描述的任何激励。",
  "training.lessons.owner-give-rewards.step3": "奖励会带着自己的一次性验证码到达，并提醒该人员的铃铛。他们在收银台出示验证码；店主或经理输入它以标记为已使用。",
  "training.lessons.owner-give-rewards.step4": "打印或共享的奖励小票只带有您企业的名称——绝不带应用的名称。这是您门店的感谢，不是广告。",
  "training.lessons.owner-give-rewards.title": "发放奖励（Business 套餐）",
  "training.lessons.owner-rewards-oversight.step1": "您的经理也可以发放奖励——仅限员工。应用会拒绝经理奖励自己或另一位经理；奖励经理始终是您的决定。",
  "training.lessons.owner-rewards-oversight.step2": "您可以在“奖励历史”中看到企业中的每份奖励：谁发放的、谁收到的，以及它是可用、已使用还是已作废。经理只能看到自己发放的和自己收到的奖励。",
  "training.lessons.owner-rewards-oversight.step3": "您可以作废任何奖励，包括您的经理发放的。经理可以作废自己的礼物，但永远不能作废您的。",
  "training.lessons.owner-rewards-oversight.step4": "每个验证码只能使用一次，作废的奖励永远不能使用——历史始终显示一份奖励的最终结果。",
  "training.lessons.owner-rewards-oversight.title": "监管奖励：您经理的发放",
  "training.lessons.staff-your-rewards.step1": "当您的经理或店主给您发放奖励时，您的铃铛会响。打开“员工管理”，点击“奖励”，在“我的奖励”下查看它。",
  "training.lessons.staff-your-rewards.step2": "每份奖励都有自己的验证码。请自己保管——在收银台出示验证码的人就是使用该奖励的人。",
  "training.lessons.staff-your-rewards.step3": "要使用它，请在购买时出示验证码。收银台的人会输入它并标记为已使用——每个验证码只能使用一次。",
  "training.lessons.staff-your-rewards.step4": "奖励是 Business 套餐的福利。如果您的门店不在 Business 套餐中，“奖励”选项卡会显示一扇锁着的门——那是套餐的原因，不是错误。",
  "training.lessons.staff-your-rewards.title": "您的奖励：找到验证码并使用它",
  "training.module.rewards": "奖励与激励",
