  "pos.provider.shopify": "Shopify POS",
  "pos.provider.square": "Square",
  "pos.shopify.connect": "连接 Shopify",
  "pos.shopify.connectedToast": "Shopify 已连接。其销售现已在此计入。",
  "pos.shopify.domainPlaceholder": "your-store.myshopify.com",
  "pos.shopify.help": "Shopify POS 销售就是 Shopify 订单。连接此门店，每个订单都会自动从这里的库存中扣除其商品。",
  "pos.shopify.tokenNote": "令牌来自您 Shopify 后台的自定义应用。它只存储在服务器上，永远不会再次显示。",
  "pos.shopify.tokenPlaceholder": "来自您 Shopify 自定义应用的访问令牌",
  "pos.square.connect": "连接 Square",
  "pos.square.connectedToast": "Square 已连接。其销售现已在此计入。",
  "pos.square.failedToast": "Square 未能完成连接。您可以重试。",
  "pos.square.help": "连接 Square，收银台的每笔销售都会自动从这里的库存中扣除其商品——无需在一天结束时输入任何内容。",
  "pos.square.notConfigured": "Square 连接尚未开启。下面的 CSV 导入今天即可使用。",
  "pos.subtitle": "连接您的收银机，收银台的一笔销售就会自动从这里的库存中扣除该商品。任何东西永远不会重复计数。",
  "pos.title": "收银机连接",
  "pos.webhookPending": "我们这边的销售 Webhook 尚未开启——连接已保存，Webhook 一开启，销售就会开始到达。",
  "training.lessons.owner-pos-connect-shopify.step1": "收银机连接是 Business 套餐的一部分。Shopify POS 销售就是 Shopify 订单，因此连接按门店进行：在 Shopify 中，为您的门店创建一个自定义应用并复制其访问令牌。在“收银机连接”页面，粘贴您的门店域名（如 your-store.myshopify.com）和令牌。",
  "training.lessons.owner-pos-connect-shopify.step2": "令牌只存储在服务器上——它永远不会再次显示，连您也看不到。如果您粘贴新的，它只会替换旧的。",
  "training.lessons.owner-pos-connect-shopify.step3": "如果您有多个位置，请选择此门店的销售从哪个位置扣除。然后每个订单——无论在 Shopify 收银台还是在线——都会自动从这里的库存中扣除其商品。",
  "training.lessons.owner-pos-connect-shopify.step4": "一家门店在此连接到一个工作区。如果某个域名已在其他地方连接，应用会直言相告，而不是共享它。",
  "training.lessons.owner-pos-connect-shopify.title": "连接 Shopify POS",
  "training.lessons.owner-pos-connect-square.step1": "收银机连接是 Business 套餐的一部分。打开“收银机连接”（在“销售”菜单中），点击 Square 卡片上的“连接”。您将进入 Square 自己的页面批准连接——应用永远不会看到您的 Square 密码。",
  "training.lessons.owner-pos-connect-square.step2": "回到应用后，卡片显示“已连接”。如果您的门店有多个位置，请选择此收银机的销售从哪个位置扣除；否则销售从您的第一个位置扣除。",
  "training.lessons.owner-pos-connect-square.step3": "从那时起，每笔 Square 销售都会自动从这里的库存中扣除商品。在收银台卖出一件商品，然后查看同一页面上的“最近销售”列表：销售会在片刻内到达，标记为已计入。",
  "training.lessons.owner-pos-connect-square.step4": "一笔销售永远不会重复计数——如果 Square 再次发送同一笔销售，应用会识别它且不做任何更改。断开连接也在同一张卡片上，它会立即停止匹配。",
  "training.lessons.owner-pos-connect-square.title": "连接 Square：为您移动库存的销售",
  "training.lessons.owner-pos-csv.step1": "任何能导出销售文件的收银机仍然可以为您的库存提供数据。将当天的销售导出为包含以下列的 CSV：sale_id、sold_at、sku_or_barcode、quantity——item_name 和 location 有帮助，但可选。",
  "training.lessons.owner-pos-csv.step2": "在“收银机连接”页面上传文件。每个 sale_id 只记录一次：明天再次上传同一文件不会有任何变化，只会报告重复项。",
  "training.lessons.owner-pos-csv.step3": "应用无法使用的行永远不会被悄悄跳过——没有 sale_id 的行，或数量不是数字的行，会连同行号和原因一起列回给您。",
  "training.lessons.owner-pos-csv.step4": "商品按 SKU 或条形码匹配，与实时收银机完全相同。任何未匹配的商品都会在匹配页面等待，与任何其他销售一样。",
  "training.lessons.owner-pos-csv.title": "没有收银机 API？用日终 CSV",
  "training.lessons.owner-pos-mapping.step1": "收银机商品按 SKU 或条形码与您的产品匹配。当一笔销售进来、带有应用从未见过的商品时，该商品会被暂挂——库存不动，销售在“收银机连接”页面的“等待匹配的商品”下等待。",
  "training.lessons.owner-pos-mapping.step2": "选择该商品真正对应的产品并保存。该匹配会被永久记住：该商品的每笔未来销售都会自动计入。",
  "training.lessons.owner-pos-mapping.step3": "保存后，点击“应用于暂挂销售”以计入等待中的销售——它们会立即写入库存变动，带有销售自己的参考编号。",
  "training.lessons.owner-pos-mapping.step4": "如果一笔暂挂销售要求的数量超过货架上的数量，它会保持标记为库存不足，而不是让数量变为负数。补货后，再从同一页面重新应用。",
  "training.lessons.owner-pos-mapping.title": "当收银机商品不匹配时：匹配页面",
  "training.lessons.owner-pos-sales-list.step1": "“收银机连接”页面上的“最近销售”列表显示您的收银机发送的每笔销售：哪个收银机、销售编号、何时、收银机报告的总计，以及每件商品的处理结果。",
  "training.lessons.owner-pos-sales-list.step2": "“已计入”表示库存已移动。“部分计入”表示有些商品已计入，有些在等待或数量不足——打开销售以通俗语言查看是哪些。",
  "training.lessons.owner-pos-sales-list.step3": "“已暂挂”表示该销售中尚无任何商品计入：有商品需要匹配（见匹配课程）、货架数量不足，或销售在门店不在 Business 套餐时到达。这三种情况都可从同一页面修复——因套餐暂挂的销售在门店回到 Business 后可从这里计入——且任何东西都不会悄无声息地丢失。",
  "training.lessons.owner-pos-sales-list.step4": "每笔已计入的销售都会在您的库存历史中写入一条正常的“已售出”记录，带有指明收银机和销售的参考编号——因此您的“变动记录”页面和收银机始终讲述同一个故事。",
  "training.lessons.owner-pos-sales-list.title": "阅读您的收银机销售",
  "training.lessons.staff-pos-till-sales.step1": "如果您的门店在 Business 套餐中并已连接收银机（Square 或 Shopify POS），收银台的每笔销售都会自动从这里的库存中扣除该商品——无需扫码出库，无需事后输入。",
  "training.lessons.staff-pos-till-sales.step2": "您可以在“收银机连接”页面上观看这一过程：每笔销售显示售出了什么、多少，以及是否计入。已计入的销售会以通俗语言显示为已计入。",
  "training.lessons.staff-pos-till-sales.step3": "有时一笔销售会被暂挂：收银机售出了应用尚无法匹配到产品的商品。库存未被扣除——销售会等待，直到店主或经理将该商品匹配一次（匹配页面）。之后，它会被计入，同一商品的下一笔销售会自动匹配。",
  "training.lessons.staff-pos-till-sales.step4": "如果一笔暂挂销售与您刚卖出的东西有关，请告诉您的经理或店主——一次快速匹配就能永久修复它。绝不要手动调整库存来弥补暂挂销售；一旦匹配，那会重复计数。",
  "training.lessons.staff-pos-till-sales.title": "当收银机售出时，您的库存会自动移动",
