  "pos.zettle.help": "连接 PayPal Zettle，收银台的每笔购买都会自动从这里的库存中扣除其商品。",
  "pos.zettle.connect": "连接 Zettle",
  "pos.zettle.connectedToast": "Zettle 已连接。其销售现已在此计入。",
